<script setup lang="ts">
import TaskHistory from '../components/TaskHistory.vue';
import {computed,ref} from 'vue';import {ui,clock} from '../state/device';import {t} from '../state/appearance';import TrendChart from '../components/TrendChart.vue';import MiniTrend from '../components/MiniTrend.vue';import Icon from '../components/Icon.vue';import InfoButton from '../components/InfoButton.vue';
const query=ref(''),sort=ref<'cpu'|'stack'|'name'>('cpu'),selected=ref('');
function closeTask(){const button=document.querySelector('.task-table tr.selected .task-link') as HTMLElement|null;selected.value='';button?.focus();}
const isIdle=(name:string)=>/^IDLE\d*$/i.test(name);
const tasks=computed(()=>ui.tasks.filter(t=>isIdle(t.name)||t.name.toLowerCase().includes(query.value.toLowerCase())).slice().sort((a,b)=>{
 const idleA=isIdle(a.name),idleB=isIdle(b.name);
 if(idleA!==idleB)return idleA?-1:1;
 if(idleA)return a.name.localeCompare(b.name,undefined,{numeric:true});
 return sort.value==='cpu'?(b.cpu_pct??-1)-(a.cpu_pct??-1):sort.value==='stack'?a.stack_min_free_bytes-b.stack_min_free_bytes:a.name.localeCompare(b.name);
}));
const task=computed(()=>ui.tasks.find(t=>t.id===selected.value));
const states=computed<Record<string,string>>(()=>({running:t('Выполняется','Running'),ready:t('Готова','Ready'),blocked:t('Ожидание','Blocked'),suspended:t('Приостановлена','Suspended'),deleted:t('Удалена','Deleted')}));
const icons:Record<string,string>={running:'player-play-filled',ready:'circle-check',blocked:'hourglass',suspended:'player-pause',deleted:'x'};
const integer=(value:number|bigint)=>value.toLocaleString(t('ru-RU','en-US'));
</script>
<template>
 <section class="panel tasks-panel" data-testid="tasks-panel"><div class="panel-head"><h2><Icon name="list-details"/>{{t('Задачи','Tasks')}} <small class="muted" :data-tooltip="ui.tasksLastSeen?new Date(ui.tasksLastSeen).toLocaleTimeString():t('Ожидание снимка','Waiting for snapshot')">/ FreeRTOS · {{ui.httpWanted?'HTTP':t('снимок','snapshot')}}</small></h2><InfoButton label="CPU / FreeRTOS" help-key="tasks"/></div>
  <div class="toolbar"><input v-model="query" :placeholder="t('Найти задачу','Find task')" :aria-label="t('Поиск задачи','Find task')"><div class="effect-buttons task-sort" role="group" :aria-label="t('Сортировка задач','Sort tasks')"><button type="button" :aria-pressed="sort==='cpu'" :class="{active:sort==='cpu'}" @click="sort='cpu'">CPU ↓</button><button type="button" :aria-pressed="sort==='stack'" :class="{active:sort==='stack'}" @click="sort='stack'">{{t('Стек ↑','Stack ↑')}}</button><button type="button" :aria-pressed="sort==='name'" :class="{active:sort==='name'}" @click="sort='name'">{{t('Имя','Name')}}</button></div></div>
  <TaskHistory/>
  <div class="table-wrap"><table class="task-table" data-testid="task-table"><colgroup><col/><col class="task-state-col"/><col class="task-cpu-col"/><col class="task-priority-col"/><col class="task-core-col"/><col class="task-stack-col"/></colgroup><thead><tr><th>{{t('Задача','Task')}}</th><th class="task-state-heading" :aria-label="t('Состояние','State')" :data-tooltip="t('Состояние задачи','Task state')"><Icon name="circle-dot"/></th><th class="numeric"><div class="task-cpu-cell"><span :data-tooltip="t('Загрузка CPU, %','CPU load, %')">%</span><span class="task-history-heading" :data-tooltip="t('История CPU, 60 секунд, 0–100%','CPU history, 60 seconds, 0–100%')"><Icon name="chart-bar"/></span></div></th><th class="numeric" :data-tooltip="t('Приоритет задачи','Task priority')" :aria-label="t('Приоритет','Priority')">P</th><th class="numeric" :data-tooltip="t('Номер ядра; * — без привязки','Core number; * means no affinity')" :aria-label="t('Ядро','Core')">C</th><th class="numeric" :data-tooltip="t('Минимальный свободный стек с запуска, байт','Minimum free stack since creation, bytes')" :aria-label="t('Минимум стека, байт','Minimum stack, bytes')">B</th></tr></thead><tbody><tr v-for="v in tasks" :key="v.id" :class="{selected:v.id===selected}"><td><button class="task-link" :data-tooltip="v.name+' · '+v.id" :aria-pressed="v.id===selected" @click="selected=v.id">{{v.name}}</button></td><td class="task-state"><span class="task-state-icon" :class="v.state" role="img" tabindex="0" :aria-label="states[v.state]??v.state" :data-tooltip="states[v.state]??v.state"><Icon :name="icons[v.state]??'question-mark'"/></span></td><td class="numeric"><div class="task-cpu-cell"><span>{{v.cpu_pct===null?'—':v.cpu_pct.toFixed(1)}}</span><MiniTrend :points="ui.taskHistory[v.id]??[]" :max="100" :stale="!ui.httpOnline" :label="v.name+' · CPU · 60 s · 0–100%'"/></div></td><td class="numeric">{{integer(v.priority)}}</td><td class="numeric">{{v.core_affinity===null?'*':integer(v.core_affinity)}}</td><td class="numeric" :class="{'warning-text':v.stack_min_free_bytes<512}">{{integer(v.stack_min_free_bytes)}}</td></tr></tbody></table></div>
 </section>
 <section v-if="task" class="panel task-inspector"><div class="panel-head"><h2>{{task.name}}</h2><div><span>{{clock(ui.summary?.uptime_ms??0)}}</span><button class="icon-button" :aria-label="t('Закрыть подробности задачи','Close task details')" @click="closeTask"><Icon name="x"/></button></div></div><div class="task-detail"><div><span>Runtime</span><strong class="mono" :data-tooltip="integer(task.runtime_ticks)+' ticks'">{{integer(task.runtime_ticks)}} ticks</strong></div><div><span>{{t('Мин. стек','Min. stack')}}</span><strong>{{integer(task.stack_min_free_bytes)}} B</strong></div></div><TrendChart :points="ui.taskHistory[task.id]??[]" :max="100" :label="t('История CPU задачи ','Task CPU history: ')+task.name"/></section>
</template>
